#define MEMO_CAP 1024u
typedef struct { unsigned long long key; unsigned long long val; int used; } slot_t;
static slot_t memo[MEMO_CAP];

unsigned long long costly(unsigned long long n) {
    size_t i = hash(n) % MEMO_CAP;
    while (memo[i].used && memo[i].key != n) i = (i + 1) % MEMO_CAP;   /* linear probe */
    if (!memo[i].used) { memo[i].key = n; memo[i].val = compute(n); memo[i].used = 1; }
    return memo[i].val;
}

